The UI primary flow validation fails at step 65 "upload button \"Select backup file\"" because the current WebFileInput component uses the experimental `window.showOpenFilePicker` API, which does not trigger a Playwright `filechooser` event. The UI validator expects a standard `<input type="file">` element that opens the file chooser when the button is clicked. Update `src/components/ui/WebFileInput.tsx` to use a hidden `<input type="file">` element triggered by the button press. Example fix:
```tsx
import React, { useRef } from 'react';
import { Platform } from 'react-native';
import PrimaryButton from './PrimaryButton';

export default function WebFileInput({
  label,
  onFileSelected,
}: {
  label: string;
  onFileSelected: (content: string) => void;
}) {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePress = () => {
    if (Platform.OS === 'web') {
      fileInputRef.current?.click();
    } else {
      // Native fallback – no file picker needed for UI flow.
    }
  };

  const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const text = await file.text();
      onFileSelected(text);
    } catch {
      // ignore errors
    }
  };

  return (
    <>
      <PrimaryButton label={label} variant="secondary" onPress={handlePress} />
      {Platform.OS === 'web' && (
        <input
          type="file"
          ref={fileInputRef}
          style={{ display: 'none' }}
          onChange={handleChange}
        />
      )}
    </>
  );
}
```
This change ensures the button labeled "Select backup file" opens a native file chooser, satisfying the UI flow test.
